// Normalize coverage from different sources
const manual = $('Manual Add').item?.json || null;
const alerts = $('Google Alerts RSS').item?.json || null;

const coverageItems = [];

// Process manual add
if (manual && manual.url) {
  coverageItems.push({
    url: manual.url,
    outlet: manual.outlet || 'Unknown',
    title: manual.title || '',
    source: 'manual'
  });
}

// Process Google Alerts (RSS feed)
if (alerts && alerts.feed && alerts.feed.entry) {
  const entries = Array.isArray(alerts.feed.entry) ? alerts.feed.entry : [alerts.feed.entry];
  entries.forEach(entry => {
    coverageItems.push({
      url: entry.link?.href || entry.link || '',
      outlet: new URL(entry.link?.href || entry.link || '').hostname,
      title: entry.title || '',
      source: 'google_alerts'
    });
  });
}

if (coverageItems.length === 0) {
  return { json: { no_coverage: true } };
}

return coverageItems.map(c => ({ json: c }));

const coverage = $('Normalize Coverage').item.json;
const items = $input.first().json.apify_items || [];
const article = items[0] || {};

return {
  json: {
    ...coverage,
    article_title: article.title || coverage.title || '',
    article_author: article.author || '',
    article_published_at: article.publishedAt || article.published_at || '',
    article_excerpt: article.description || article.excerpt || '',
    article_text: article.text || article.content || ''
  }
};

values.content:
=Classify this media coverage for Sako:

URL: {{ $json.url }}
Outlet: {{ $json.outlet }}
Title: {{ $json.article_title || $json.title }}
Author: {{ $json.article_author }}
Published: {{ $json.article_published_at }}
Excerpt: {{ $json.article_excerpt }}
Content: {{ ($json.article_text || '').slice(0, 1200) }}

## Classification Types
1. **earned_interview** - Reporter/host actively chose to feature Sako (interview, dedicated article, podcast appearance)
2. **syndicated** - Press release picked up and republished without editorial selection
3. **quote** - Founder quoted in a broader story (not the main subject)
4. **mention** - Brief mention without substance

## Output (JSON only)
{
  "type": "earned_interview|syndicated|quote|mention",
  "badge_allowed": true|false,
  "confidence": 0.0-1.0,
  "reasoning": "one sentence"
}

Note: badge_allowed should be true ONLY for earned_interview and quote types.

parameters.jsCode:
// Parse classification result
const coverage = $('Normalize Article').item.json;
const classificationText = $input.first().json.text;

// Try to parse JSON from response
let classification;
try {
  const jsonMatch = classificationText.match(/\{[\s\S]*\}/);
  classification = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  classification = { type: 'mention', badge_allowed: false, confidence: 0.5 };
}

return {
  json: {
    url: coverage.url,
    outlet: coverage.outlet,
    title: coverage.article_title || coverage.title,
    author: coverage.article_author,
    published_at: coverage.article_published_at,
    type: classification.type || 'mention',
    date: new Date().toISOString(),
    badge_allowed: classification.badge_allowed || false,
    confidence: classification.confidence || 0.5,
    reasoning: classification.reasoning || ''
  }
};

